dtsPropsFor.EventList:
/** Build with filterEvents(events, { when, types: [] }, now) from the bundle. Empty array renders the "no events" message. */
  results: { event: { id: string; type: "demonstration" | "rally" | "action" | "assembly" | "camp" | "other"; title: string; description: string | null; organizer: string | null; lat: number; lng: number; placeLabel: string | null; municipality: string; district: string; tz: "Europe/Lisbon" | "Atlantic/Madeira" | "Atlantic/Azores"; verified: boolean; occurrences: { id: string; localDate: string; startTime: string | null; endTime: string | null; startsAt: string; endsAt: string; note: string | null; cancelled: boolean }[] }; highlight: { id: string; localDate: string; startTime: string | null; endTime: string | null; startsAt: string; endsAt: string; note: string | null; cancelled: boolean }; inRange: { id: string; localDate: string; startTime: string | null; endTime: string | null; startsAt: string; endsAt: string; note: string | null; cancelled: boolean }[]; others: { id: string; localDate: string; startTime: string | null; endTime: string | null; startsAt: string; endsAt: string; note: string | null; cancelled: boolean }[] }[];
  selectedId: string | null;
  onSelect: (id: string) => void;

dtsPropsFor.EventSheet:
/** null shows the loading / not-found state. */
  event: { id: string; type: "demonstration" | "rally" | "action" | "assembly" | "camp" | "other"; title: string; description: string | null; organizer: string | null; lat: number; lng: number; placeLabel: string | null; municipality: string; district: string; tz: "Europe/Lisbon" | "Atlantic/Madeira" | "Atlantic/Azores"; verified: boolean; occurrences: { id: string; localDate: string; startTime: string | null; endTime: string | null; startsAt: string; endsAt: string; note: string | null; cancelled: boolean }[] } | null;
  /** true while fetching an event that is not in the map data */
  loading: boolean;
  when: { kind: "upcoming" } | { kind: "today" } | { kind: "tomorrow" } | { kind: "weekend" } | { kind: "next7" } | { kind: "day"; date: string };
  now: Date;
  onClose: () => void;

dtsPropsFor.FilterPanel:
id: string;
  when: { kind: "upcoming" } | { kind: "today" } | { kind: "tomorrow" } | { kind: "weekend" } | { kind: "next7" } | { kind: "day"; date: string };
  /** Selected types; empty = all. */
  types: ("demonstration" | "rally" | "action" | "assembly" | "camp" | "other")[];
  typeCounts: Record<"demonstration" | "rally" | "action" | "assembly" | "camp" | "other", number>;
  /** Use countByDay(events, types, now, 14) from the bundle. */
  dayCounts: { date: string; count: number }[];
  /** YYYY-MM-DD in Europe/Lisbon; lisbonToday(now). */
  today: string;
  dayStripOpen: boolean;
  isDefault: boolean;
  resultsLabel: string;
  /** Mobile overlay mode: shows a close button (non-modal). */
  overlay: boolean;
  onWhen: (when: { kind: "upcoming" } | { kind: "today" } | { kind: "tomorrow" } | { kind: "weekend" } | { kind: "next7" } | { kind: "day"; date: string }) => void;
  onToggleType: (type: "demonstration" | "rally" | "action" | "assembly" | "camp" | "other") => void;
  onToggleDayStrip: () => void;
  onClear: () => void;
  onClose: () => void;

dtsPropsFor.OccurrencesEditor:
/** One row per date; make new rows with emptyRow(). */
  rows: { key: string; id?: string; localDate: string; allDay: boolean; startTime: string; endTime: string; note: string; cancelled: boolean; past?: boolean }[];
  onChange: (rows: { key: string; id?: string; localDate: string; allDay: boolean; startTime: string; endTime: string; note: string; cancelled: boolean; past?: boolean }[]) => void;
  /** Field errors keyed by path, e.g. { "occurrences.0.localDate": "..." }. */
  errors: Record<string, string>;
  tz: "Europe/Lisbon" | "Atlantic/Madeira" | "Atlantic/Azores" | null;
  /** Earliest selectable date (YYYY-MM-DD). */
  minDate: string;
  maxDate: string;
  /** "edit": existing rows get cancel/restore instead of only remove. */
  mode: "create" | "edit";

dtsPropsFor.EventDetailsFields:
/** Start from emptyDetails(). */
  value: { type: "demonstration" | "rally" | "action" | "assembly" | "camp" | "other" | ""; title: string; description: string; organizer: string; placeLabel: string };
  onChange: (next: { type: "demonstration" | "rally" | "action" | "assembly" | "camp" | "other" | ""; title: string; description: string; organizer: string; placeLabel: string }) => void;
  /** Field errors keyed by field name, e.g. { title: "..." }. */
  errors: Record<string, string>;
  /** Show the place label field here (edit page). */
  withPlaceLabel?: boolean;
